#!/usr/bin/env python3
"""Add UCI controls needed to transport AbilityFish search state."""
from pathlib import Path
import sys

if len(sys.argv) != 2:
    raise SystemExit("usage: apply_fairy_protocol_hooks.py PATH_TO_FAIRY_STOCKFISH")
root=Path(sys.argv[1]).resolve(); p=root/'src'/'uci.cpp'
if not p.exists(): raise SystemExit(f"not a Fairy-Stockfish checkout: {root}")
s=p.read_text()
if 'ABILITYFISH_UCI_HOOKS_V3' in s:
    print('AbilityFish UCI hooks already applied'); raise SystemExit(0)
anchor='''      else if (token == "setoption")  setoption(is);\n      // UCCI-specific banmoves command\n'''
hook='''      else if (token == "setoption")  setoption(is);\n      // ABILITYFISH_UCI_HOOKS_V3\n      else if (token == "abilityfish")\n      {\n          std::string mode; is >> mode;\n          pos.set_abilityfish_active(mode != "off" && mode != "0" && mode != "false");\n          sync_cout << "info string abilityfish " << (pos.abilityfish_active() ? "on" : "off") << sync_endl;\n      }\n      else if (token == "abilitypoints")\n      {\n          int white = 0, black = 0; is >> white >> black;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          ast.side[abilityfish::side_index(abilityfish::Side::White)].points = uint8_t(std::clamp(white, 0, 255));\n          ast.side[abilityfish::side_index(abilityfish::Side::Black)].points = uint8_t(std::clamp(black, 0, 255));\n          ast.recompute_key();\n          sync_cout << "info string abilitypoints " << white << " " << black << sync_endl;\n      }\n      else if (token == "abilityturn")\n      {\n          std::string side; int remaining = 1, dbl = 0, beganCheck = 0;\n          is >> side >> remaining >> dbl >> beganCheck;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          ast.turn = side == "b" ? abilityfish::Side::Black : abilityfish::Side::White;\n          ast.boardMovesRemaining = uint8_t(std::clamp(remaining, 0, 255));\n          ast.doubleMoveActive = dbl != 0;\n          ast.beganTurnInCheck = beganCheck != 0;\n          ast.recompute_key();\n      }\n      else if (token == "abilityused")\n      {\n          int white = 0, black = 0; is >> white >> black;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          ast.side[0].abilityUsedThisTurn = white != 0;\n          ast.side[1].abilityUsedThisTurn = black != 0;\n          ast.recompute_key();\n      }\n      else if (token == "abilityflags")\n      {\n          int abilities = 1, upgrades = 1, limit = 3; is >> abilities >> upgrades >> limit;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          ast.abilitiesEnabled = abilities != 0;\n          ast.upgradesEnabled = upgrades != 0;\n          ast.upgradeLimit = uint8_t(std::clamp(limit, 0, 6));\n          ast.recompute_key();\n      }\n      else if (token == "abilitytimed")\n      {\n          std::string kind, side; int sq = 64, turns = 0, active = 0;\n          is >> kind >> side >> sq >> turns >> active;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          auto& ss = ast.side[side == "b" ? 1 : 0];\n          abilityfish::TimedSquare value{abilityfish::Square{uint8_t(std::clamp(sq,0,64))}, uint8_t(std::clamp(turns,0,255)), active != 0};\n          if (kind == "shield") ss.shield = value;\n          else if (kind == "freeze") ss.frozenEnemy = value;\n          else if (kind == "ambush") ss.ambush = value;\n          ast.recompute_key();\n      }\n      else if (token == "abilityfortify")\n      {\n          std::string side; int q0=64,q1=64,q2=64,q3=64,turns=0,active=0;\n          is >> side >> q0 >> q1 >> q2 >> q3 >> turns >> active;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          auto cv=[](int q){ return abilityfish::Square{uint8_t(std::clamp(q,0,64))}; };\n          ast.side[side == "b" ? 1 : 0].fortify = {{cv(q0),cv(q1),cv(q2),cv(q3)}, uint8_t(std::clamp(turns,0,255)), active != 0};\n          ast.recompute_key();\n      }\n      else if (token == "abilitylastmove")\n      {\n          std::string side; int from=64,to=64,code=0,valid=0; is >> side >> from >> to >> code >> valid;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          ast.side[side == "b" ? 1 : 0].lastMove = {abilityfish::Square{uint8_t(std::clamp(from,0,64))}, abilityfish::Square{uint8_t(std::clamp(to,0,64))}, uint8_t(std::clamp(code,0,255)), valid != 0};\n          ast.recompute_key();\n      }\n      else if (token == "abilityportal")\n      {\n          int idx=0,a=64,b=64,turns=0,active=0; std::string owner; is >> idx >> a >> b >> owner >> turns >> active;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          idx = std::clamp(idx,0,1);\n          ast.portals[idx] = {abilityfish::Square{uint8_t(std::clamp(a,0,64))}, abilityfish::Square{uint8_t(std::clamp(b,0,64))}, owner == "b" ? abilityfish::Side::Black : abilityfish::Side::White, uint8_t(std::clamp(turns,0,255)), active != 0};\n          ast.recompute_key();\n      }\n      else if (token == "abilityupgrade")\n      {\n          std::string side; int pieceTypeIndex=-1, encoded=0; is >> side >> pieceTypeIndex >> encoded;\n          pos.set_abilityfish_active(true);\n          auto& ast = pos.ability_state();\n          if (pieceTypeIndex >= 0 && pieceTypeIndex < 6)\n          {\n              if (encoded <= 0) ast.clear_upgrade(side == "b" ? abilityfish::Side::Black : abilityfish::Side::White, uint8_t(pieceTypeIndex));\n              else if (encoded <= int(abilityfish::Upgrade::Count)) ast.set_upgrade(side == "b" ? abilityfish::Side::Black : abilityfish::Side::White, uint8_t(pieceTypeIndex), abilityfish::Upgrade(encoded - 1));\n          }\n          ast.recompute_key();\n      }\n      // UCCI-specific banmoves command\n'''
if s.count(anchor)!=1: raise SystemExit(f'uci anchor expected once, found {s.count(anchor)}')
s=s.replace(anchor,hook,1); p.write_text(s)
print('Applied AbilityFish UCI hooks')